def parse(data: bytes):
    """Parse the binary format read by reader.c.

    Returns the canonical structure (header / records) or None if the
    input is malformed.
    """
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    end = len(data)

    # The C reader rejects anything larger than 65536 bytes and requires
    # room for the 5-byte prefix plus the 4-byte record count.
    if end > 65536 or end < 9:
        return None

    offset = 0

    def read_number(width):
        nonlocal offset
        if offset > end or width > end - offset:
            return None
        value = 0
        for i in range(width):
            value |= data[offset + i] << (8 * i)
        offset += width
        return value

    actual_magic = (
        data[0]
        | (data[1] << 8)
        | (data[2] << 16)
        | (data[3] << 24)
    )
    if actual_magic != 0x710E19D5:
        return None
    if data[4] != 0x1B:
        return None
    offset = 5

    record_count = read_number(4)
    if record_count is None or record_count > 8:
        return None

    status = read_number(1)
    if status is None:
        return None
    sequence = read_number(1)
    if sequence is None:
        return None

    records = []
    for _ in range(record_count):
        enabled = read_number(4)
        if enabled is None:
            return None
        count = read_number(1)
        if count is None:
            return None
        rec_sequence = read_number(2)
        if rec_sequence is None:
            return None
        flags = read_number(2)
        if flags is None:
            return None
        stock = read_number(4)
        if stock is None:
            return None
        records.append(
            {
                "count": count,
                "enabled": enabled,
                "flags": flags,
                "sequence": rec_sequence,
                "stock": stock,
            }
        )

    if offset != end:
        return None

    return {
        "header": {"sequence": sequence, "status": status},
        "records": records,
    }
